# Python feature flag integration with LaunchDarkly for LLM variant selection
import ldclient
from ldclient.config import Config
import openai

ld_client = ldclient.get()

def generate_response(user_id, user_context, query):
    # Define user context for targeting
    user = {
        "key": user_id,
        "custom": {
            "tier": user_context.get("subscription"),
            "industry": user_context.get("industry"),
            "region": user_context.get("region")
        }
    }

    # Evaluate flags for LLM configuration
    model_variant = ld_client.variation(
        "llm-model-selection", user, "gpt-3.5-turbo"
    )
    system_prompt = ld_client.variation(
        "system-prompt-template", user, "default_prompt"
    )
    temperature = ld_client.variation(
        "temperature-setting", user, 0.7
    )

    # Track experiment exposure
    ld_client.track("llm-inference", user, None, {
        "model": model_variant,
        "prompt_version": system_prompt
    })

    # Execute LLM call with flagged configuration
    response = openai.ChatCompletion.create(
        model=model_variant,
        temperature=temperature,
        messages=[
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": query}
        ]
    )

    return response.choices[0].message.content
